-- ----------------------------
-- Table structure for sys_tenant_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_tenant_config`;
CREATE TABLE `sys_tenant_config`  (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT '租户ID',
  `package_id` bigint NULL DEFAULT NULL COMMENT '套餐ID',
  `start_time` datetime NULL DEFAULT NULL COMMENT '套餐开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '套餐结束时间',
  `current_users` int NULL DEFAULT 0 COMMENT '当前用户数',
  `current_storage` bigint NULL DEFAULT 0 COMMENT '当前存储使用量(MB)',
  `status` int NULL DEFAULT 1 COMMENT '状态: 1-正常, -1-过期, -2-禁用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint NULL DEFAULT NULL COMMENT '创建人',
  `update_user` bigint NULL DEFAULT NULL COMMENT '更新人',
  `deleted` int NULL DEFAULT 0 COMMENT '逻辑删除标识(0:未删除;-1:已删除)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id` ASC) USING BTREE,
  INDEX `idx_package_id`(`package_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租户配置表（关联租户和套餐）' ROW_FORMAT = Dynamic;

